const MILESTONES = contentConfig.milestones;

// Dense interpolated chart data for smooth Robinhood-style price line
const CHART_DATA = (() => {
    const STEPS = 5;
    const NOISE = [0.11, -0.08, 0.16, -0.05, 0.13, -0.10, 0.07, -0.14, 0.18, -0.06, 0.12, -0.09, 0.15, -0.04, 0.10, -0.12, 0.17, -0.07, 0.09, -0.11, 0.14, -0.06, 0.08, -0.13, 0.16, -0.05, 0.11, -0.09, 0.19, -0.08, 0.10, -0.12, 0.15, -0.06, 0.13, -0.08, 0.17, -0.07, 0.09, -0.11, 0.12, -0.06, 0.18, -0.08, 0.14, -0.10, 0.08, -0.13, 0.16, -0.05, 0.11, -0.09, 0.15, -0.07, 0.10, -0.12, 0.13, -0.05, 0.17, -0.08];
    const out = [];
    let ni = 0;
    for (let i = 0; i < MILESTONES.length; i++) {
        const m = MILESTONES[i];
        const next = MILESTONES[i + 1];
        if (!next) {
            out.push({ year: m.year, value: m.value, milestone: m.milestone, desc: m.desc, isMilestone: true, isLast: true });
            break;
        }
        for (let s = 0; s < STEPS; s++) {
            const t = s / STEPS;
            const ease = t * t * (3 - 2 * t);
            const base = m.value + (next.value - m.value) * ease;
            const n = NOISE[ni++ % NOISE.length];
            out.push({
                year: s === 0 ? m.year : "",
                value: parseFloat((base + n).toFixed(2)),
                milestone: s === 0 ? m.milestone : null,
                desc: s === 0 ? m.desc : null,
                isMilestone: s === 0,
                isLast: false,
            });
        }
    }
    return out;
})();

