const LiveDot = (props) => {
    const { cx, cy, payload } = props;
    if (payload.isLast) {
        return <circle cx={cx} cy={cy} r={5} fill="#00c805" stroke="#0d1117" strokeWidth={2} className="blinking-dot" />;
    }
    if (payload.isMilestone) {
        return <circle cx={cx} cy={cy} r={3} fill="#00c805" stroke="#0d1117" strokeWidth={1.5} opacity={0.75} />;
    }
    return null;
};


