import React, { useState, useRef, useEffect } from "react";

const STORAGE_KEY = "navbar-position";

const snapToSide = (x, nodeWidth) => {
  const mid = window.innerWidth / 2;
  return x + nodeWidth / 2 < mid ? "left" : "right";
};

const defaultSide = () => {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (saved && (saved.side === "left" || saved.side === "right")) return saved;
  } catch (_) {}
  return { side: "left", y: window.innerHeight / 2 - 40 };
};

export default function LeftNavBar({ onConnect, onProfile }) {
  const [showMenu, setShowMenu] = useState(false);
  const [snap, setSnap] = useState(defaultSide);
  const [dragging, setDragging] = useState(false);
  const [dragPos, setDragPos] = useState(null);
  const offset = useRef({ x: 0, y: 0 });
  const containerRef = useRef(null);

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: "smooth" });

  const sections = [
    { id: "home",           label: "🏠 Home",           action: scrollToTop },
    { id: "profile",        label: "👤 Profile",         action: onProfile },
    { id: "connect",        label: "🔗 Connect",         action: onConnect, highlight: true },
    { id: "experience",     label: "💼 Experience" },
    { id: "education",      label: "🎓 Education" },
    { id: "projects",       label: "📊 Projects" },
    { id: "skills",         label: "🧠 Skills" },
    { id: "certifications", label: "📜 Certifications" },
    { id: "awards",         label: "🏆 Awards" },
  ];

  const handleNavClick = (id, action) => {
    if (action) return action();
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  const onMouseDown = (e) => {
    const node = containerRef.current;
    const rect = node.getBoundingClientRect();
    offset.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    setDragging(true);
    setDragPos({ x: rect.left, y: rect.top });
    e.preventDefault();
  };

  useEffect(() => {
    const onMouseMove = (e) => {
      if (!dragging) return;
      const node = containerRef.current;
      const h = node ? node.offsetHeight : 80;
      const newY = Math.max(0, Math.min(window.innerHeight - h, e.clientY - offset.current.y));
      setDragPos({ x: e.clientX - offset.current.x, y: newY });
    };

    const onMouseUp = (e) => {
      if (!dragging) return;
      const node = containerRef.current;
      const w = node ? node.offsetWidth : 80;
      const h = node ? node.offsetHeight : 80;
      const finalY = Math.max(0, Math.min(window.innerHeight - h, e.clientY - offset.current.y));
      const side = snapToSide(e.clientX - offset.current.x, w);
      const newSnap = { side, y: finalY };
      setSnap(newSnap);
      setDragging(false);
      setDragPos(null);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newSnap));
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
    return () => {
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };
  }, [dragging]);

  const isRight = !dragging && snap.side === "right";

  const style = dragging && dragPos
    ? { left: dragPos.x, top: dragPos.y }
    : snap.side === "left"
      ? { left: 0, top: snap.y }
      : { right: 0, top: snap.y };

  return (
    <div
      ref={containerRef}
      className="fixed z-50 select-none"
      style={style}
      onMouseEnter={() => setShowMenu(true)}
      onMouseLeave={() => setShowMenu(false)}
    >
      <div className={`flex items-stretch ${isRight ? "flex-row-reverse" : "flex-row"}`}>
        {/* Drag grip */}
        <div
          onMouseDown={onMouseDown}
          className="cursor-grab active:cursor-grabbing bg-green-500/10 hover:bg-green-500/30 border border-green-500/20 px-1.5 flex flex-col gap-0.5 items-center justify-center"
          style={{ borderRadius: isRight ? "0.5rem 0 0 0.5rem" : "0 0.5rem 0.5rem 0" }}
          title="Drag to left or right edge"
        >
          {[...Array(6)].map((_, i) => (
            <span key={i} className="block w-1 h-1 rounded-full bg-green-500/60" />
          ))}
        </div>

        {/* Home button — always visible */}
        <button
          onClick={scrollToTop}
          className={`bg-green-500/20 hover:bg-green-500/40 text-green-300 font-bold px-4 py-2 border border-green-500/30 transition ${
            isRight ? "rounded-tl-lg rounded-bl-lg" : "rounded-tr-lg rounded-br-lg"
          }`}
        >
          🏠
        </button>
      </div>

      {/* Slide-in nav menu (hover) */}
      <div
        className={`transition-all duration-300 overflow-hidden ${
          showMenu ? "max-h-[500px] opacity-100 mt-1" : "max-h-0 opacity-0"
        } bg-[#0b0f16]/95 border border-green-500/30 ${isRight ? "rounded-l-xl" : "rounded-r-xl"}`}
      >
        <ul className="flex flex-col text-left p-2">
          {sections.map((s) => (
            <li key={s.id}>
              <button
                onClick={() => handleNavClick(s.id, s.action)}
                className={`block w-full text-left py-2 px-3 rounded-md transition text-sm font-medium ${
                  s.highlight
                    ? "text-black bg-green-500 hover:bg-green-400 my-0.5"
                    : "text-green-300 hover:text-green-400 hover:bg-green-500/10"
                }`}
              >
                {s.label}
              </button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
