import React, { useState } from "react";
import { motion } from "framer-motion";
import { Star, Eye } from "lucide-react";

export default function BlogPost({ 
  id, 
  title, 
  cover, 
  tags, 
  date, 
  stars, 
  views, 
  type,
  excerpt,
  content,
  author 
}) {
  const [liked, setLiked] = useState(false);
  const [likeCount, setLikeCount] = useState(stars);
  const [expanded, setExpanded] = useState(false);

  const handleLike = () => {
    setLiked(!liked);
    setLikeCount(liked ? likeCount - 1 : likeCount + 1);
  };

  const getTypeColor = (type) => {
    const colors = {
      blog: "bg-blue-500/20 text-blue-400 border-blue-500/30",
      publication: "bg-purple-500/20 text-purple-400 border-purple-500/30",
      paper: "bg-orange-500/20 text-orange-400 border-orange-500/30",
      research: "bg-red-500/20 text-red-400 border-red-500/30",
    };
    return colors[type] || colors.blog;
  };

  return (
    <motion.div
      className="w-full max-w-2xl bg-[#0d1117] border border-green-500/30 rounded-2xl overflow-hidden hover:border-green-400 hover:shadow-[0_0_25px_rgba(34,197,94,0.3)] transition cursor-pointer"
      whileHover={{ y: -5 }}
      transition={{ duration: 0.3 }}
      onClick={() => setExpanded(!expanded)}
    >
      {/* Cover Image Section */}
      <div className="relative h-48 bg-red-600 overflow-hidden">
        {cover ? (
          <img 
            src={cover} 
            alt={title} 
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full bg-red-600 flex items-center justify-center">
            <span className="text-white text-4xl">📄</span>
          </div>
        )}
      </div>

      {/* Title Bar Section (Green Bar) */}
      <div className="bg-gradient-to-r from-green-600 to-green-700 px-6 py-4 border-b border-green-500/30">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-2">
          <h3 className="text-white text-lg font-bold flex-1 line-clamp-2">{title}</h3>
          <span className={`px-3 py-1 rounded-full text-xs font-semibold border flex-shrink-0 ${getTypeColor(type)}`}>
            {type.charAt(0).toUpperCase() + type.slice(1)}
          </span>
        </div>
      </div>

      {/* Content Section */}
      <div className="p-6">
        {/* Tags */}
        <div className="flex flex-wrap gap-2 mb-4">
          {tags.map((tag, idx) => (
            <span
              key={idx}
              className="bg-gray-800 border border-gray-700 text-gray-300 text-[11px] px-2 py-2 rounded-md shadow-inner"
            >
              {tag}
            </span>
          ))}
        </div>

        {/* Excerpt */}
        {excerpt && (
          <p className="text-gray-300 text-sm mb-4 line-clamp-3">
            {excerpt}
          </p>
        )}

        {/* Meta Info */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between text-sm text-gray-400 py-3 border-t border-gray-700/30 gap-3">
          <div className="flex items-center gap-2 text-xs text-gray-300 uppercase tracking-wide">
            <span className="font-semibold">Date posted</span>
            <span>{new Date(date).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })}</span>
          </div>
          <div className="flex items-center gap-5">
            <button
              onClick={(e) => {
                e.stopPropagation();
                handleLike();
              }}
              className="flex items-center gap-1 hover:text-yellow-400 transition group"
            >
              <Star
                size={16}
                className={`transition ${liked ? "fill-yellow-400 text-yellow-400" : "group-hover:fill-yellow-400"}`}
              />
              <span className="text-xs">{likeCount}</span>
            </button>
            <div className="flex items-center gap-1 text-gray-400">
              <Eye size={16} />
              <span className="text-xs">{views.toLocaleString()}</span>
            </div>
          </div>
        </div>

        {/* Expanded Content */}
        {expanded && content && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="mt-4 pt-4 border-t border-gray-700/30"
          >
            <p className="text-gray-300 text-sm leading-relaxed">{content}</p>
            <p className="text-gray-500 text-xs mt-3">- {author || "Nachiketh Joshi"}</p>
          </motion.div>
        )}
      </div>
    </motion.div>
  );
}
